#!/usr/bin/env python3
"""Theme cursor build/deploy pipeline. Art is generated by image_gen, never here."""
from __future__ import annotations
import argparse, copy, datetime, hashlib, importlib.util, io, json, os, platform
import plistlib, re, shutil, subprocess, sys, tempfile, uuid, zipfile
from pathlib import Path

SCALES=(1,2,5,10)
DOMAIN='com.sdmj76.Mousecape'
APP=Path('/Applications/Mousecape.app')
SYSTEM=Path('/System/Library/Frameworks/ApplicationServices.framework/Versions/A/Frameworks/HIServices.framework/Versions/A/Resources/cursors')
LIBRARY=Path.home()/'Library/Application Support/Mousecape/capes'
PREF_KEYS=('MCAppliedCursor','lastAppliedCapeIdentifier','capeListOrder','MCCursorScale','launchAtLogin')
IDS={
 'normal':'com.apple.coregraphics.Arrow','text':'com.apple.coregraphics.IBeam',
 'action':'com.apple.cursor.13','forbidden':'com.apple.cursor.3','busy':'com.apple.cursor.4',
 'open_hand':'com.apple.cursor.12','resize_horizontal':'com.apple.cursor.19',
 'resize_vertical':'com.apple.cursor.23','crosshair':'com.apple.cursor.7',
 'closed_hand':'com.apple.cursor.11','resize_nw_se':'com.apple.cursor.34',
 'resize_ne_sw':'com.apple.cursor.30','help':'com.apple.cursor.40',
 'move':'com.apple.coregraphics.Move','copy':'com.apple.coregraphics.Copy',
 'alias':'com.apple.coregraphics.Alias','zoom_in':'com.apple.cursor.42',
 'zoom_out':'com.apple.cursor.43','context_menu':'com.apple.cursor.24',
 'camera':'com.apple.cursor.10','text_horizontal':'com.apple.cursor.26'}
DEFAULT_STATES=tuple(list(IDS)[:12])
LABELS=dict(zip(DEFAULT_STATES,('正常选择','文字输入','链接 / 点击','不可用','忙碌中','移动画布',
 '左右调整','上下调整','精准选择','抓取 / 拖动','左上 ↔ 右下','右上 ↔ 左下')))
LABELS.update(help='帮助选择',move='四向移动',copy='复制拖动',alias='创建别名',
 zoom_in='放大',zoom_out='缩小',context_menu='上下文菜单',camera='截取窗口',text_horizontal='横向文本')
ALIASES={
 'com.apple.coregraphics.ArrowS':'normal','com.apple.coregraphics.ArrowCtx':'normal',
 'com.apple.coregraphics.IBeamS':'text','com.apple.coregraphics.IBeamXOR':'text',
 'com.apple.cursor.2':'action','com.apple.coregraphics.Wait':'busy',
 'com.apple.cursor.8':'crosshair','com.apple.cursor.28':'resize_horizontal',
 'com.apple.cursor.32':'resize_vertical','com.apple.cursor.33':'resize_nw_se',
 'com.apple.cursor.35':'resize_nw_se','com.apple.cursor.29':'resize_ne_sw',
 'com.apple.cursor.37':'resize_ne_sw'}
EMPTY='com.apple.coregraphics.Empty'
SAFE_ID=re.compile(r'^[A-Za-z0-9][A-Za-z0-9.-]{0,180}$')

def require(condition, message):
    if not condition: raise ValueError(message)

def read_json(path):
    return json.loads(Path(path).read_text(encoding='utf-8'))

def write_json(path, value):
    Path(path).parent.mkdir(parents=True,exist_ok=True)
    Path(path).write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')

def atomic_write(path,data):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True)
    with tempfile.NamedTemporaryFile(dir=path.parent,delete=False) as f:
        name=f.name;f.write(data)
    try: os.replace(name,path)
    finally:
        if os.path.exists(name): os.unlink(name)

def decode_image(data):
    from PIL import Image
    with Image.open(io.BytesIO(data)) as im: return im.convert('RGBA')

def preferences():
    # Read through CFPreferences via defaults so an app's cached values are respected.
    result=subprocess.run(['defaults','export',DOMAIN,'-'],capture_output=True,timeout=15)
    if result.returncode: return {}
    values=plistlib.loads(result.stdout)
    return {k:values[k] for k in PREF_KEYS if k in values}

def set_preference(key,value):
    require(key in PREF_KEYS,'unsupported preference')
    cmd=['defaults','write',DOMAIN,key]
    if isinstance(value,list): cmd+=['-array',*[str(x) for x in value]]
    elif isinstance(value,bool): cmd+=['-bool','true' if value else 'false']
    elif isinstance(value,(int,float)): cmd+=['-float',str(value)]
    elif value is None:
        subprocess.run(['defaults','delete',DOMAIN,key],capture_output=True,timeout=15);return
    else: cmd+=['-string',str(value)]
    subprocess.run(cmd,capture_output=True,timeout=15,check=True)

def doctor(app=APP):
    app=Path(app);cli=app/'Contents/MacOS/mousecloak'
    info={}
    if (app/'Contents/Info.plist').is_file():
        info=plistlib.loads((app/'Contents/Info.plist').read_bytes())
    return {'platform':platform.system(),'python':sys.executable,
      'pillow':importlib.util.find_spec('PIL') is not None,
      'pypdfium2':importlib.util.find_spec('pypdfium2') is not None,
      'app':str(app),'app_version':info.get('CFBundleShortVersionString'),
      'bundle_identifier':info.get('CFBundleIdentifier'),
      'cli_available':cli.is_file() and os.access(cli,os.X_OK),
      'system_fallback_pdfs':all((SYSTEM/n/'cursor.pdf').is_file() for n in ('copy','makealias','move')),
      'library':str(LIBRARY),'preferences':preferences() if platform.system()=='Darwin' else {}}

def init_project(theme,out,states=None):
    out=Path(out).resolve();out.mkdir(parents=True,exist_ok=True)
    path=out/'brief.json';require(not path.exists(),'brief.json already exists; edit or resume it')
    states=states or DEFAULT_STATES
    require(set(states)<=set(IDS),'unknown state')
    require({'normal','text','action','forbidden'}<=set(states),'four core states are required')
    slug=hashlib.sha256(theme.encode()).hexdigest()[:10]
    manifest={'theme':{'name':theme+' · 指尖小队','identifier':'local.cursor.theme-'+slug,
      'author':'自定义','version':1,'platform':'macos','preview_style':'chibi-anime',
      'preview_title':theme+' · 指尖小队','preview_subtitle':f'{len(states)} 种动作，把主题带到指尖。',
      'preview_footer':'主题预览 / 热点已校准'},
      'generation':{'provider':'built-in image_gen','model':None},
      'artworks':{s:{'source':f'source-art/{s}.png','source_hotspot':None,
          'character_name':'','prompt':'','review':'PENDING'} for s in states}}
    (out/'source-art').mkdir(exist_ok=True);write_json(path,manifest)
    return {'brief':str(path),'states':list(states),'next':'assign characters, generate independent alpha PNGs, inspect and fill source_hotspot/prompt/review'}

def normalize_art(state,item,root,out):
    from PIL import Image
    require(item.get('review')=='PASS',f'{state}: inspect the actual image and mark PASS first')
    require(bool(item.get('prompt')),f'{state}: actual generation prompt is required')
    source_path=(root/item['source']).resolve()
    require(source_path.is_file(),f'{state}: missing source {source_path}')
    with Image.open(source_path) as original:
        require(original.format=='PNG' and 'A' in original.getbands(),f'{state}: true alpha PNG required')
        require(min(original.size)>=320 and max(original.size)<=8192,f'{state}: source must be 320–8192 px')
        im=original.convert('RGBA')
    alpha=im.getchannel('A').point(lambda a:0 if a<=8 else a);im.putalpha(alpha)
    bbox=alpha.getbbox()
    require(bbox is not None,f'{state}: blank source')
    require(min(bbox[0],bbox[1],im.width-bbox[2],im.height-bbox[3])>0,
        f'{state}: source artwork touches edge; repair original, do not hide clipping by padding')
    point=item.get('source_hotspot')
    require(isinstance(point,list) and len(point)==2 and all(isinstance(v,(int,float)) for v in point),
        f'{state}: source_hotspot needs two source-pixel coordinates')
    sx,sy=point
    require(0<=sx<im.width and 0<=sy<im.height,f'{state}: source hotspot out of bounds')
    require(alpha.getpixel((round(sx),round(sy)))>=128,f'{state}: hotspot is transparent; inspect correct functional point')
    cropped=im.crop(bbox);factor=832/max(cropped.size)
    w,h=[round(v*factor) for v in cropped.size];ox,oy=(1024-w)//2,(1024-h)//2
    hx=ox+(sx-bbox[0])*w/cropped.width;hy=oy+(sy-bbox[1])*h/cropped.height
    hotspot=[round(hx/32),round(hy/32)]
    ox+=round(hotspot[0]*32-hx);oy+=round(hotspot[1]*32-hy)
    norm=Image.new('RGBA',(1024,1024))
    norm.alpha_composite(cropped.resize((w,h),Image.Resampling.LANCZOS),(ox,oy))
    normpath=out/'normalized'/f'{state}.png';normpath.parent.mkdir(exist_ok=True);norm.save(normpath)
    paths=[];reps=[]
    for scale in SCALES:
        rep=norm.resize((32*scale,32*scale),Image.Resampling.LANCZOS)
        require(rep.getchannel('A').getpixel((hotspot[0]*scale,hotspot[1]*scale))>0,f'{state}: reduced hotspot lost')
        p=out/'retina'/f'{state}@{scale}x.png';p.parent.mkdir(exist_ok=True);rep.save(p)
        paths.append(str(p.relative_to(out)));reps.append(p.read_bytes())
    rec={'FrameCount':1,'FrameDuration':1.0,'HotSpotX':hotspot[0],'HotSpotY':hotspot[1],
      'PointsWide':32,'PointsHigh':32,'Representations':reps}
    cursor={'identifier':IDS[state],'path':paths[0],'representations':paths,'hotspot':hotspot,
      'preview_source':str(normpath.relative_to(out)),'character_name':item.get('character_name','')}
    check={'source':str(source_path),'sha256':hashlib.sha256(source_path.read_bytes()).hexdigest(),
      'source_bounds':bbox,'source_hotspot':point,'hotspot':hotspot}
    return rec,cursor,check

def native_fallbacks(existing,out):
    from PIL import Image
    records={};provenance=[]
    for role,name in [('copy','copy'),('alias','makealias'),('move','move'),('empty',None)]:
        identifier=EMPTY if role=='empty' else IDS[role]
        if identifier in existing: continue
        if name:
            import pypdfium2 as pdfium
            source=SYSTEM/name/'cursor.pdf';require(source.is_file(),f'missing system asset: {source}')
            doc=pdfium.PdfDocument(source);page=doc[0];w,h=map(int,page.get_size())
            info=plistlib.loads((SYSTEM/name/'info.plist').read_bytes());hx,hy=info['hotx'],info['hoty']
        else: w=h=32;hx=hy=0
        reps=[]
        for scale in SCALES:
            im=(page.render(scale=scale,fill_color=(0,0,0,0)).to_pil().convert('RGBA') if name
                else Image.new('RGBA',(w*scale,h*scale)))
            require(im.size==(w*scale,h*scale),'system raster dimensions differ')
            p=out/'system-fallbacks'/f'{role}@{scale}x.png';p.parent.mkdir(exist_ok=True)
            im.save(p);reps.append(p.read_bytes())
        records[identifier]={'FrameCount':1,'FrameDuration':1.0,'HotSpotX':hx,'HotSpotY':hy,
            'PointsWide':w,'PointsHigh':h,'Representations':reps}
        provenance.append({'identifier':identifier,'source':str(source) if name else 'transparent RGBA'})
        if name: page.close();doc.close()
    write_json(out/'system-fallbacks/source-record.json',provenance)
    return records

def validate_payload(payload):
    require(payload.get('Version')==2 and payload.get('MinimumVersion')==2,'Mousecape format must be 2')
    require(bool(SAFE_ID.fullmatch(payload.get('Identifier',''))),'unsafe or missing identifier')
    require(payload.get('HiDPI') is True,'HiDPI must be true')
    cursors=payload.get('Cursors',{})
    require({IDS[s] for s in ('normal','text','action','forbidden')}<=set(cursors),'missing core states')
    for key,c in cursors.items():
        w,h=c['PointsWide'],c['PointsHigh'];x,y=c['HotSpotX'],c['HotSpotY']
        require(c['FrameCount']==1 and c['FrameDuration']>0,f'{key}: static frame required')
        require(0<w<=512 and 0<h<=512 and 0<=x<w and 0<=y<h,f'{key}: invalid geometry')
        require(len(c['Representations'])==4,f'{key}: four density representations required')
        for scale,data in zip(SCALES,c['Representations']):
            require(data.startswith(b'\x89PNG\r\n\x1a\n'),f'{key}: package representations must be PNG')
            im=decode_image(data)
            require(im.size==(round(w*scale),round(h*scale)),f'{key}: representation size mismatch')
            alpha=im.getchannel('A');bbox=alpha.getbbox()
            if key==EMPTY: require(bbox is None,'Empty must be fully transparent')
            else:
                require(bbox is not None,f'{key}: blank artwork')
                require(alpha.getpixel((round(x*scale),round(y*scale)))>0,f'{key}: transparent hotspot')
    require(EMPTY in cursors,'explicit Empty record required to prevent stale visible hidden cursor')
    return {'identifier':payload['Identifier'],'record_count':len(cursors),'hidpi':True,'empty_transparent':True}

def load_cape(path):
    return plistlib.loads(Path(path).read_bytes())

def render_sizes(cursors,out):
    from PIL import Image,ImageDraw
    states=list(cursors);cols=min(6,len(states));rows=(len(states)+cols-1)//cols
    board=Image.new('RGB',(cols*190,rows*480),'white');draw=ImageDraw.Draw(board)
    for i,state in enumerate(states):
        x=(i%cols)*190;y=(i//cols)*480
        for band,bg in enumerate(('white','#102032')):
            by=y+band*240;draw.rectangle((x,by,x+190,by+240),fill=bg)
            draw.text((x+8,by+6),state,fill='#142033' if band==0 else 'white')
            art=Image.open(out/cursors[state]['preview_source']).convert('RGBA')
            for size,yy in [(32,28),(64,67),(96,137)]:
                im=art.resize((size,size),Image.Resampling.LANCZOS);board.paste(im,(x+(190-size)//2,by+yy),im)
    board.save(out/'size-check.png')

def build(brief_path,preview_only=False):
    from preview_design import render
    brief_path=Path(brief_path).resolve();root=brief_path.parent;brief=read_json(brief_path)
    theme=brief['theme'];arts=brief['artworks']
    require(theme.get('platform')=='macos','this skill currently deploys macOS only')
    require(bool(SAFE_ID.fullmatch(theme['identifier'])),'unsafe identifier')
    require(set(arts)<=set(IDS),'unsupported artwork state')
    require({'normal','text','action','forbidden'}<=set(arts),'missing core states')
    require(bool(brief.get('generation',{}).get('provider')),'generation provenance required')
    cursors={};records={};checks={}
    for state,item in arts.items():
        record,cursor,check=normalize_art(state,item,root,root)
        cursors[state]=cursor;records[IDS[state]]=record;checks[state]=check
    require(len({c['sha256'] for c in checks.values()})==len(checks),'artwork states must use independently drawn poses')
    for state,cursor in cursors.items():
        im=decode_image(records[IDS[state]]['Representations'][-1])
        b=im.getchannel('A').getbbox();require(min(b[0],b[1],im.width-b[2],im.height-b[3])>=6,f'{state}: insufficient transparent border')
    artmanifest={'theme':theme,'cursors':cursors}
    write_json(root/'artwork-manifest.json',artmanifest)
    render(artmanifest,root,[(s,c,records[IDS[s]]['Representations']) for s,c in cursors.items()],root/'preview.png',LABELS)
    render_sizes(cursors,root)
    for identifier,state in ALIASES.items():
        if state in arts: records[identifier]=copy.deepcopy(records[IDS[state]])
    themed_count=len(records)
    if 'copy' in arts: records['com.apple.cursor.5']=copy.deepcopy(records[IDS['copy']]);themed_count+=1
    checks_record={'artwork_count':len(arts),'themed_record_count':themed_count,'artworks':checks,'preview_only':preview_only}
    if not preview_only:
        records.update(native_fallbacks(records,root))
        payload={'Author':theme.get('author','自定义'),'CapeName':theme['name'],
          'CapeVersion':theme.get('version',1),'Cloud':False,'HiDPI':True,'Identifier':theme['identifier'],
          'MinimumVersion':2,'Version':2,'Cursors':records}
        validate_payload(payload);atomic_write(root/'theme.cape',plistlib.dumps(payload,fmt=plistlib.FMT_BINARY))
        checks_record['cape_sha256']=hashlib.sha256((root/'theme.cape').read_bytes()).hexdigest()
        checks_record['record_count']=len(records)
    write_json(root/'build-verification.json',checks_record)
    return {'project':str(root),'preview':str(root/'preview.png'),'artwork_count':len(arts),
      'cape':str(root/'theme.cape') if not preview_only else None,'records':len(records)}

def run_cli(app,args,log):
    cli=Path(app)/'Contents/MacOS/mousecloak'
    result=subprocess.run([str(cli),*map(str,args),'--suppress-copyright'],capture_output=True,timeout=60)
    Path(log).parent.mkdir(parents=True,exist_ok=True)
    Path(log).write_bytes(result.stdout+result.stderr)
    require(result.returncode==0,f'mousecloak failed; inspect {log}')
    return (result.stdout+result.stderr).decode(errors='replace')

def compare_capes(expected,actual):
    from PIL import Image,ImageChops,ImageStat
    results=[]
    for identifier,wanted in expected['Cursors'].items():
        require(identifier in actual.get('Cursors',{}),f'missing applied cursor: {identifier}')
        got=actual['Cursors'][identifier]
        for field in ('FrameCount','HotSpotX','HotSpotY','PointsWide','PointsHigh'):
            require(got[field]==wanted[field],f'{identifier}: {field} differs')
        require(len(got['Representations'])==len(wanted['Representations']),f'{identifier}: density count differs')
        scores=[]
        for w,g in zip(wanted['Representations'],got['Representations']):
            a,b=decode_image(w),decode_image(g);require(a.size==b.size,f'{identifier}: actual dimensions differ')
            for bg in ('white','black'):
                base=Image.new('RGBA',a.size,bg)
                diff=ImageChops.difference(Image.alpha_composite(base,a),Image.alpha_composite(base,b))
                score=max(ImageStat.Stat(diff).rms)
                require(score<3,f'{identifier}: visible pixels differ (RMS {score:.3f})')
                scores.append(round(score,3))
        if identifier==EMPTY:
            require(all(decode_image(r).getchannel('A').getbbox() is None for r in got['Representations']),
                'applied Empty cursor is visible')
        results.append({'identifier':identifier,'hotspot_and_sizes_match':True,'max_visible_pixel_rms':max(scores)})
    return results

def verify(cape,report,app=APP,actual=None,check_preferences=True):
    cape=Path(cape).resolve();report=Path(report).resolve()
    expected=load_cape(cape);validate_payload(expected);report.parent.mkdir(parents=True,exist_ok=True)
    if actual is None:
        actual=report.parent/'actual-system.cape'
        run_cli(app,['dump',actual],report.parent/'dump.log')
    results=compare_capes(expected,load_cape(actual))
    prefs=preferences() if check_preferences else {}
    if check_preferences:
        require(prefs.get('MCAppliedCursor')==expected['Identifier'],'current applied preference differs')
        require(prefs.get('lastAppliedCapeIdentifier')==expected['Identifier'],'persistent selection differs')
    value={'system_records_verified':True,'identifier':expected['Identifier'],'record_count':len(results),
      'cape_sha256':hashlib.sha256(cape.read_bytes()).hexdigest(),'empty_fully_transparent':True,
      'preferences_checked':check_preferences,'cursor_scale':prefs.get('MCCursorScale'),
      'launch_at_login':prefs.get('launchAtLogin'),'ui_verified':False,'records':results}
    write_json(report,value)
    return value

def apply_checked(cape,app,log):
    output=run_cli(app,['apply',cape],log)
    failed=re.findall(r'Failed:\s*(\d+)',output)
    if failed: require(int(failed[-1])==0,f'apply reported failed records; inspect {log}')
    success=re.findall(r'Successfully applied:\s*(\d+)',output)
    if success: require(int(success[-1])==len(load_cape(cape)['Cursors']),'apply count differs')
    # Exit zero and even a successful summary are insufficient: verify() is mandatory next.

def runtime_scale(app,log):
    import math
    value=float(run_cli(app,['scale'],log).strip())
    require(math.isfinite(value) and value>0,'invalid runtime cursor scale')
    return value

def restore_transaction(tx,app=APP):
    tx=Path(tx);info=read_json(tx/'transaction.json');target=Path(info['installed_path'])
    require(target.parent.resolve()==LIBRARY.resolve(),'rollback target is outside the Mousecape library')
    previous=tx/'previous-installed.cape'
    if previous.exists(): atomic_write(target,previous.read_bytes())
    else: target.unlink(missing_ok=True)
    snapshot=load_cape(tx/'before-system.cape')
    before=info['before_preferences'];old_id=before.get('MCAppliedCursor')
    snapshot['Identifier']=old_id or 'local.cursor.restored-session'
    snap=tx/'restore-system.cape';atomic_write(snap,plistlib.dumps(snapshot,fmt=plistlib.FMT_BINARY))
    apply_checked(snap,app,tx/'rollback-apply.log')
    actual=tx/'rollback-actual.cape';run_cli(app,['dump',actual],tx/'rollback-dump.log')
    compare_capes(snapshot,load_cape(actual))
    scale=info.get('before_runtime_scale',before.get('MCCursorScale'))
    if scale is not None: run_cli(app,['scale',scale],tx/'rollback-scale.log')
    for key in PREF_KEYS:
        set_preference(key,before.get(key))
    after=preferences()
    require(all(after.get(k)==before.get(k) for k in PREF_KEYS),'rollback preferences did not restore')
    if scale is not None:
        require(abs(runtime_scale(app,tx/'rollback-scale-check.log')-scale)<0.0001,'rollback runtime scale differs')
    info['rolled_back']=True;write_json(tx/'transaction.json',info)
    for report_path in (tx/'verification.json',tx.parent.parent/'deployment-verification.json'):
        if report_path.is_file():
            report=read_json(report_path)
            report.update(applied=False,ui_verified=False,rolled_back=True,rollback_transaction=str(tx))
            write_json(report_path,report)
    return {'rolled_back':True,'transaction':str(tx)}

def deploy(cape,app=APP,dry_run=False):
    import fcntl
    cape=Path(cape).resolve();payload=load_cape(cape);summary=validate_payload(payload)
    build_report=cape.parent/'build-verification.json'
    if build_report.exists():
        built=read_json(build_report)
        require(not built.get('preview_only'),'latest build is preview-only; do not deploy an older cape')
        require(built.get('cape_sha256')==hashlib.sha256(cape.read_bytes()).hexdigest(),'cape differs from latest build')
    health=doctor(app);require(health['platform']=='Darwin','deployment requires macOS')
    require(health['cli_available'],'Mousecape CLI unavailable; inspect/install official Mousecape first')
    require(health.get('bundle_identifier')==DOMAIN,'Mousecape bundle identifier differs; adapt doctor before deployment')
    target=LIBRARY/f"{payload['Identifier']}.cape"
    if dry_run: return {'dry_run':True,'source':str(cape),'target':str(target),**summary,'current':health['preferences']}
    LIBRARY.mkdir(parents=True,exist_ok=True)
    with open(LIBRARY/'.theme-cursor.lock','w') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        stamp=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'-'+uuid.uuid4().hex[:6]
        tx=cape.parent/'deployments'/stamp;tx.mkdir(parents=True)
        before=preferences()
        before_scale=runtime_scale(app,tx/'before-scale.log')
        if target.exists(): shutil.copy2(target,tx/'previous-installed.cape')
        run_cli(app,['dump',tx/'before-system.cape'],tx/'before-dump.log')
        require(bool(load_cape(tx/'before-system.cape').get('Cursors')),'empty rollback snapshot')
        info={'installed_path':str(target),'before_preferences':before,'before_runtime_scale':before_scale,'source':str(cape),'rolled_back':False}
        write_json(tx/'transaction.json',info)
        try:
            atomic_write(target,cape.read_bytes())
            apply_checked(target,app,tx/'apply.log')
            set_preference('lastAppliedCapeIdentifier',payload['Identifier'])
            order=list(before.get('capeListOrder',[]))
            if payload['Identifier'] not in order: order.append(payload['Identifier'])
            set_preference('capeListOrder',order)
            report=verify(target,tx/'verification.json',app)
            now=preferences()
            for key in ('MCCursorScale','launchAtLogin'):
                require(now.get(key)==before.get(key),f'{key} unexpectedly changed')
            require(abs(runtime_scale(app,tx/'after-scale.log')-before_scale)<0.0001,'runtime cursor scale unexpectedly changed')
            report.update(installed_path=str(target),transaction=str(tx),applied=True,
                          previous_theme_identifier=before.get('MCAppliedCursor'))
            write_json(tx/'verification.json',report)
            write_json(cape.parent/'deployment-verification.json',report)
            return {k:v for k,v in report.items() if k!='records'}
        except Exception as error:
            info['failure']=str(error);write_json(tx/'transaction.json',info)
            try: restore_transaction(tx,app)
            except Exception as restore_error:
                raise RuntimeError(f'Deploy failed: {error}; rollback also failed: {restore_error}. Evidence: {tx}') from error
            raise RuntimeError(f'Deploy failed and prior system snapshot was restored: {error}. Evidence: {tx}') from error

def package(project):
    root=Path(project).resolve();cape=root/'theme.cape'
    built=read_json(root/'build-verification.json')
    require(not built.get('preview_only'),'preview-only output has no install package; deliver the preview images')
    require(cape.is_file(),'theme.cape is missing; complete build first')
    require(built.get('cape_sha256')==hashlib.sha256(cape.read_bytes()).hexdigest(),'cape differs from latest build; rebuild before packaging')
    payload=load_cape(cape);validate_payload(payload)
    report_path=root/'deployment-verification.json'
    deployed=False
    if report_path.is_file():
        report=read_json(report_path)
        deployed=(report.get('applied') is True and not report.get('rolled_back') and report.get('cape_sha256')==hashlib.sha256(cape.read_bytes()).hexdigest())
        if deployed and platform.system()=='Darwin':
            deployed=preferences().get('MCAppliedCursor')==payload['Identifier']
    status='本机系统记录已读回验证通过。' if deployed else '此包已校验，尚未确认本机应用。'
    text=f"# {payload['CapeName']}\n\n{status}\n\n在 Mousecape 中：文件 → 导入 Cape → 选择 theme.cape → 选中主题 → 应用。\n\n角色按应用请求的鼠标状态切换，不随机轮换。缩放与登录启动沿用现有设置；应用自绘光标可能保持自身图案。\n\n切回旧主题：在 Mousecape 列表中选原主题并应用。部署脚本还保留 deployments 下的完整状态备份。\n\npreview.png 中的红色十字仅表示热点，不会出现在实际鼠标中。\n"
    (root/'使用说明.md').write_text(text,encoding='utf-8')
    files=['theme.cape','preview.png','使用说明.md','build-verification.json']
    if report_path.is_file(): files.append('deployment-verification.json')
    archive=root/'鼠标主题-安装包.zip'
    with zipfile.ZipFile(archive,'w',zipfile.ZIP_DEFLATED) as z:
        for name in files:
            require((root/name).is_file(),f'missing package file: {name}')
            z.write(root/name,'鼠标主题/'+name)
    with zipfile.ZipFile(archive) as z: require(z.testzip() is None,'corrupt ZIP')
    return {'archive':str(archive),'applied_verified':deployed,'bytes':archive.stat().st_size}

def main():
    p=argparse.ArgumentParser(description=__doc__);subs=p.add_subparsers(dest='cmd',required=True)
    s=subs.add_parser('doctor');s.add_argument('--app',type=Path,default=APP)
    s=subs.add_parser('init');s.add_argument('--theme',required=True);s.add_argument('--out',type=Path,required=True);s.add_argument('--states',help='comma-separated artwork states')
    s=subs.add_parser('build');s.add_argument('--brief',type=Path,required=True);s.add_argument('--preview-only',action='store_true')
    s=subs.add_parser('validate');s.add_argument('--cape',type=Path,required=True)
    s=subs.add_parser('deploy');s.add_argument('--cape',type=Path,required=True);s.add_argument('--app',type=Path,default=APP);s.add_argument('--dry-run',action='store_true')
    s=subs.add_parser('verify');s.add_argument('--cape',type=Path,required=True);s.add_argument('--report',type=Path,required=True);s.add_argument('--app',type=Path,default=APP);s.add_argument('--actual',type=Path);s.add_argument('--no-preferences',action='store_true')
    s=subs.add_parser('rollback');s.add_argument('--transaction',type=Path,required=True);s.add_argument('--app',type=Path,default=APP)
    s=subs.add_parser('package');s.add_argument('--project',type=Path,required=True)
    args=p.parse_args()
    try:
        if args.cmd=='doctor': result=doctor(args.app)
        elif args.cmd=='init': result=init_project(args.theme,args.out,args.states.split(',') if args.states else None)
        elif args.cmd=='build': result=build(args.brief,args.preview_only)
        elif args.cmd=='validate': result=validate_payload(load_cape(args.cape))
        elif args.cmd=='deploy': result=deploy(args.cape,args.app,args.dry_run)
        elif args.cmd=='verify':
            result=verify(args.cape,args.report,args.app,args.actual,not args.no_preferences)
            result={k:v for k,v in result.items() if k!='records'}
        elif args.cmd=='rollback': result=restore_transaction(args.transaction,args.app)
        else: result=package(args.project)
        print(json.dumps(result,ensure_ascii=False,indent=2))
    except Exception as error:
        print(json.dumps({'error':str(error),'command':args.cmd},ensure_ascii=False),file=sys.stderr);return 1
    return 0
if __name__=='__main__': raise SystemExit(main())
